def canon(step):
 d=json.loads(json.dumps(step)); d.pop('if',None)
 if d.get('uses','').startswith('actions/checkout@'):
  w=d.get('with',{}); w.pop('fetch-depth',None)
  if not w:d.pop('with',None)
 if d.get('uses','').startswith('codecov/codecov-action@'):
  d.get('with',{}).pop('version',None)
 return json.dumps(d,sort_keys=True)
